pub fn F_hydkernels__culvertInflow(p_q_proposed: f64, p_head: f64, p_y_full: f64, p_a_full: f64, p_slope: f64, p_cc: ?*T_hydkernels_CulvertCurve, p_mitered: bool, p_dqdh: *f64) E!f64 {
    var q_proposed = p_q_proposed;
    _ = &q_proposed;
    var head = p_head;
    _ = &head;
    var y_full = p_y_full;
    _ = &y_full;
    var a_full = p_a_full;
    _ = &a_full;
    var slope = p_slope;
    _ = &slope;
    var cc = p_cc;
    _ = &cc;
    var mitered = p_mitered;
    _ = &mitered;
    var dqdh = p_dqdh;
    _ = &dqdh;
