    _ = &AD;
    var y_norm: f64 = (head / y_full);
    _ = &y_norm;
    var scf: f64 = @as(f64, if (mitered) (@as(f64, -7.0) * slope) else (@as(f64, 0.5) * slope));
    _ = &scf;
