    } else {
        if ((y_norm >= y2_norm)) {
            var arg_2: f64 = (((y_norm - cc.?.Y) + scf) / cc.?.C);
            _ = &arg_2;
            if ((arg_2 <= @as(f64, 0.0))) {
                return q_proposed;
            }
            q_inlet = (AD * rt.Math.Sqrt_d(arg_2));
            dqdh.* = ((@as(f64, 0.5) * q_inlet) / ((arg_2 * y_full) * cc.?.C));
        } else {
            var arg1: f64 = (y1_norm / cc.?.K);
            _ = &arg1;
