            _ = &q1;
            var arg2: f64 = (((y2_norm - cc.?.Y) + scf) / cc.?.C);
            _ = &arg2;
            var q2: f64 = @as(f64, if ((arg2 > @as(f64, 0.0))) (AD * rt.Math.Sqrt_d(arg2)) else q1);
            _ = &q2;
            var frac: f64 = ((y_norm - y1_norm) / (y2_norm - y1_norm));
            _ = &frac;
            q_inlet = (q1 + (frac * (q2 - q1)));
            dqdh.* = ((q2 - q1) / ((y2_norm - y1_norm) * y_full));
        }
    }
    return (if ((q_inlet < q_proposed)) &q_inlet else &q_proposed).*;
