            while ((k < this.?.pumps_.?.count)) : (k = (k +% 1)) {
                var uk: u64 = rt.cv(u64, k);
                _ = &uk;
                var j: i32 = this.?.pumps_.?.link_idx.?.a.?[@intCast(uk)];
                _ = &j;
                var uj: u64 = rt.cv(u64, j);
                _ = &uj;
                var n1: i32 = links.?.node1.?.a.?[@intCast(uj)];
                _ = &n1;
                if ((n1 < @as(i32, 0))) {
                    continue;
                }
                var un1: u64 = rt.cv(u64, n1);
                _ = &un1;
                links.?.target_setting.?.a.?[@intCast(uj)] = links.?.setting.?.a.?[@intCast(uj)];
                var depth: f64 = nodes.?.depth.?.a.?[@intCast(un1)];
                _ = &depth;
                var y_off: f64 = this.?.pumps_.?.y_off.?.a.?[@intCast(uk)];
                _ = &y_off;
                var y_on: f64 = this.?.pumps_.?.y_on.?.a.?[@intCast(uk)];
                _ = &y_on;
                if ((((y_off > @as(f64, 0.0)) and (links.?.setting.?.a.?[@intCast(uj)] > @as(f64, 0.0))) and (depth < y_off))) {
                    links.?.target_setting.?.a.?[@intCast(uj)] = @as(f64, 0.0);
                }
                if ((((y_on > @as(f64, 0.0)) and (links.?.setting.?.a.?[@intCast(uj)] == @as(f64, 0.0))) and (depth > y_on))) {
                    links.?.target_setting.?.a.?[@intCast(uj)] = @as(f64, 1.0);
                }
            }
        }
    }
}

