pub fn T_fv_PressurizedHeadSolver__faceModeOf(p_mesh: ?*T_fv_NetworkMeshData, p_state: ?*T_fv_NetworkStateData, p_f: i32) E!u8 {
    var mesh = p_mesh;
    _ = &mesh;
    var state = p_state;
    _ = &state;
    var f = p_f;
    _ = &f;
    var uf: u64 = rt.cv(u64, f);
    _ = &uf;
    if ((rt.cv(i32, mesh.?.face_gate.?.a.?[@intCast(uf)]) != @as(i32, 0))) {
        return @as(u8, 0);
    }
    if ((mesh.?.face_culvert.?.a.?[@intCast(uf)] >= @as(i32, 0))) {
        return @as(u8, 0);
    }
    var cl: i32 = mesh.?.face_cl.?.a.?[@intCast(uf)];
    _ = &cl;
    var cr: i32 = mesh.?.face_cr.?.a.?[@intCast(uf)];
    _ = &cr;
    var nd: i32 = mesh.?.face_node.?.a.?[@intCast(uf)];
    _ = &nd;
    if (((nd < @as(i32, 0)) and ((cl < @as(i32, 0)) or (cr < @as(i32, 0))))) {
        return @as(u8, 0);
    }
    var pl: bool = false;
    _ = &pl;
    var pr: bool = false;
    _ = &pr;
    var cell_side_press: bool = false;
    _ = &cell_side_press;
    if ((cl >= @as(i32, 0))) {
        pl = (try T_fv_PressurizedHeadSolver__cellPressurized(mesh, state, cl));
        cell_side_press = (cell_side_press or pl);
    }
    if ((cr >= @as(i32, 0))) {
        pr = (try T_fv_PressurizedHeadSolver__cellPressurized(mesh, state, cr));
        cell_side_press = (cell_side_press or pr);
    }
    if ((nd >= @as(i32, 0))) {
        var gp: bool = (try T_fv_PressurizedHeadSolver__ghostPressurized(mesh, state, f));
        _ = &gp;
        if ((cl < @as(i32, 0))) {
            pl = gp;
        }
        if ((cr < @as(i32, 0))) {
            pr = gp;
        }
    }
    if (!(cell_side_press)) {
        return @as(u8, 0);
    }
    return rt.cv(u8, @as(i32, if ((pl and pr)) @as(i32, 1) else @as(i32, 2)));
}

pub fn T_fv_PressurizedHeadSolver__ghostPressurized(p_mesh: ?*T_fv_NetworkMeshData, p_state: ?*T_fv_NetworkStateData, p_f: i32) E!bool {
    var mesh = p_mesh;
    _ = &mesh;
    var state = p_state;
    _ = &state;
    var f = p_f;
    _ = &f;
    var uf: u64 = rt.cv(u64, f);
    _ = &uf;
    var nd: i32 = mesh.?.face_node.?.a.?[@intCast(uf)];
    _ = &nd;
    if ((nd < @as(i32, 0))) {
        return false;
    }
    var other: i32 = (if ((mesh.?.face_cl.?.a.?[@intCast(uf)] >= @as(i32, 0))) &mesh.?.face_cl.?.a.?[@intCast(uf)] else &mesh.?.face_cr.?.a.?[@intCast(uf)]).*;
    _ = &other;
    if ((other < @as(i32, 0))) {
        return false;
    }
    var g: ?*T_fv_FvGeometry = mesh.?.geom.?.a.?[@intCast(rt.cv(u64, mesh.?.cell_geom.?.a.?[@intCast(rt.cv(u64, other))]))];
    _ = &g;
    if ((rt.cv(i32, g.?.is_open) != @as(i32, 0))) {
        return false;
    }
    if (((!((try state.?.cell_tpa.?.empty())) and (rt.cv(i32, state.?.cell_tpa.?.a.?[@intCast(rt.cv(u64, other))]) != @as(i32, 0))) and (mesh.?.node_sur_depth.?.a.?[@intCast(rt.cv(u64, nd))] > @as(f64, 0.0)))) {
        return true;
    }
    var hg: f64 = (state.?.node_head.?.a.?[@intCast(rt.cv(u64, nd))] - mesh.?.face_zb.?.a.?[@intCast(uf)]);
    _ = &hg;
    return (hg >= g.?.y_crown);
}

