pub fn F_fv_secgeom__areaOfDepth(p_xs: ?*T_XSectParams, p_h: f64) E!f64 {
    var xs = p_xs;
    _ = &xs;
    var h = p_h;
    _ = &h;
    if ((h <= @as(f64, 0.0))) {
        return @as(f64, 0.0);
    }
    if ((h > xs.?.y_full)) {
