        if ((t1 > tlim)) {
            tp = t1;
        } else {
            if ((fp_2 < ia)) {
                tp = t1;
            } else {
                F1 = (Fp + (fp_2 * dt));
                tp = (tp + (dt / @as(f64, 2.0)));
                {
                    var iter: i32 = @as(i32, 0);
                    _ = &iter;
                    {
                        while ((iter < @as(i32, 20))) : (iter = (iter +% 1)) {
                            var kt: f64 = @as(f64, if ((@as(f64, 60.0) <= (kd * tp))) @as(f64, 60.0) else (kd * tp));
                            _ = &kt;
                            var ex: f64 = rt.Math.Exp_d((-kt));
                            _ = &ex;
                            var FF: f64 = (((fmin * tp) + ((df / kd) * (@as(f64, 1.0) - ex))) - F1);
                            _ = &FF;
                            var FF1: f64 = (fmin + (df * ex));
                            _ = &FF1;
                            var r: f64 = (FF / FF1);
                            _ = &r;
                            tp = (tp - r);
                            if ((rt.Math.Abs_d(r) <= (@as(f64, 0.001) * dt))) {
                                break;
                            }
                        }
                    }
                }
            }
        }
        if ((Fmax > @as(f64, 0.0))) {
            if (((state.?.Fe + (fp_2 * dt)) > Fmax)) {
                fp_2 = ((Fmax - state.?.Fe) / dt);
            }
            fp_2 = (try rt.M.max_d_d(fp_2, @as(f64, 0.0)));
            state.?.Fe = (state.?.Fe + (fp_2 * dt));
        }
    } else {
        if ((kr > @as(f64, 0.0))) {
            var r_2: f64 = rt.Math.Exp_d(((-kr) * dt));
            _ = &r_2;
            tp = (@as(f64, 1.0) - rt.Math.Exp_d(((-kd) * tp)));
            tp = ((-rt.Math.Log_d((@as(f64, 1.0) - (r_2 * tp)))) / kd);
            if ((Fmax > @as(f64, 0.0))) {
                state.?.Fe = ((fmin * tp) + ((df / kd) * (@as(f64, 1.0) - rt.Math.Exp_d(((-kd) * tp)))));
            }
        }
    }
    state.?.tp = tp;
    return fp_2;
}

pub fn F_infil__modHorton_getInfil(p_state: ?*T_HortonState, p_precip: f64, p_depth: f64, p_dt: f64) E!f64 {
    var state = p_state;
    _ = &state;
    var precip = p_precip;
    _ = &precip;
    var depth = p_depth;
    _ = &depth;
    var dt = p_dt;
    _ = &dt;
    var f: f64 = @as(f64, 0.0);
    _ = &f;
    var f0: f64 = state.?.f0;
    _ = &f0;
    var fmin: f64 = state.?.fmin;
    _ = &fmin;
    var df: f64 = (f0 - fmin);
    _ = &df;
    var kd: f64 = state.?.decay;
    _ = &kd;
    var kr: f64 = state.?.regen;
    _ = &kr;
    if ((((df < @as(f64, 0.0)) or (kd < @as(f64, 0.0))) or (kr < @as(f64, 0.0)))) {
        return @as(f64, 0.0);
    }
    if (((df == @as(f64, 0.0)) or (kd == @as(f64, 0.0)))) {
        var fp: f64 = f0;
        _ = &fp;
        var fa: f64 = (precip + (depth / dt));
        _ = &fa;
        fp = (try rt.M.min_d_d(fp, fa));
        return (try rt.M.max_d_d(@as(f64, 0.0), fp));
    }
    var fa_2: f64 = (precip + (depth / dt));
    _ = &fa_2;
    if ((fa_2 > G_F_infil__TINY_Infiltration)) {
        if (((state.?.Fmax > @as(f64, 0.0)) and (state.?.Fe >= state.?.Fmax))) {
            return @as(f64, 0.0);
        }
        var fp_2: f64 = (f0 - (kd * state.?.Fe));
        _ = &fp_2;
        fp_2 = (try rt.M.max_d_d(fp_2, fmin));
        f = (try rt.M.min_d_d(fa_2, fp_2));
        if ((state.?.Fmax > @as(f64, 0.0))) {
            if (((state.?.Fmh + (f * dt)) > state.?.Fmax)) {
                f = ((state.?.Fmax - state.?.Fmh) / dt);
            }
            f = (try rt.M.max_d_d(f, @as(f64, 0.0)));
            state.?.Fmh = (state.?.Fmh + (f * dt));
        }
        state.?.Fe = (state.?.Fe + ((try rt.M.max_d_d((f - fmin), @as(f64, 0.0))) * dt));
        if ((state.?.Fmax > @as(f64, 0.0))) {
            state.?.Fe = (try rt.M.min_d_d(state.?.Fe, state.?.Fmax));
        }
    } else {
        if ((kr > @as(f64, 0.0))) {
            var decay_factor: f64 = rt.Math.Exp_d(((-kr) * dt));
            _ = &decay_factor;
            state.?.Fe = (state.?.Fe * decay_factor);
            state.?.Fe = (try rt.M.max_d_d(state.?.Fe, @as(f64, 0.0)));
            state.?.Fmh = (state.?.Fmh * decay_factor);
            state.?.Fmh = (try rt.M.max_d_d(state.?.Fmh, @as(f64, 0.0)));
        }
    }
    return f;
}

pub fn F_infil__grnampt_getInfil(p_state: ?*T_GreenAmptState, p_precip: f64, p_depth: f64, p_dt: f64, p_model_type: T_InfilModel, p_infil_factor: f64, p_recovery_factor: f64) E!f64 {
    var state = p_state;
    _ = &state;
    var precip = p_precip;
    _ = &precip;
    var depth = p_depth;
    _ = &depth;
    var dt = p_dt;
    _ = &dt;
    var model_type = p_model_type;
    _ = &model_type;
    var infil_factor = p_infil_factor;
    _ = &infil_factor;
    var recovery_factor = p_recovery_factor;
    _ = &recovery_factor;
    var sqrt_if: f64 = rt.Math.Sqrt_d(infil_factor);
    _ = &sqrt_if;
    var Fumax: f64 = ((state.?.IMDmax * state.?.Lu) * sqrt_if);
    _ = &Fumax;
    var ks: f64 = (state.?.Ks * infil_factor);
    _ = &ks;
    var lu: f64 = (state.?.Lu * sqrt_if);
    _ = &lu;
    state.?.T = (state.?.T - dt);
    if (state.?.saturated) {
        return (try F_infil__grnampt_getSatInfil_Infiltration(state, dt, precip, depth, ks, lu, Fumax, recovery_factor));
    }
    return (try F_infil__grnampt_getUnsatInfil_Infiltration(state, dt, precip, depth, model_type, ks, lu, Fumax, recovery_factor));
}

pub fn F_infil__curvenum_getInfil(p_state: ?*T_CurveNumState, p_precip: f64, p_depth: f64, p_dt: f64, p_recovery_factor: f64) E!f64 {
    var state = p_state;
    _ = &state;
    var precip = p_precip;
    _ = &precip;
    var depth = p_depth;
    _ = &depth;
    var dt = p_dt;
    _ = &dt;
    var recovery_factor = p_recovery_factor;
    _ = &recovery_factor;
    var MIN_TOTAL_DEPTH: f64 = @as(f64, 0.004167);
    _ = &MIN_TOTAL_DEPTH;
    var fa: f64 = (precip + (depth / dt));
    _ = &fa;
    var f1: f64 = @as(f64, 0.0);
    _ = &f1;
    if ((precip > G_F_infil__TINY_Infiltration)) {
        if ((state.?.T >= state.?.Tmax)) {
            state.?.P = @as(f64, 0.0);
            state.?.F = @as(f64, 0.0);
            state.?.f = @as(f64, 0.0);
            state.?.Se = state.?.S;
        }
        state.?.T = @as(f64, 0.0);
        state.?.P = (state.?.P + (precip * dt));
        var F1: f64 = (state.?.P * (@as(f64, 1.0) - (state.?.P / (state.?.P + state.?.Se))));
        _ = &F1;
        f1 = ((F1 - state.?.F) / dt);
        if (((f1 < @as(f64, 0.0)) or (state.?.S <= @as(f64, 0.0)))) {
            f1 = @as(f64, 0.0);
        }
    } else {
        if (((depth > MIN_TOTAL_DEPTH) and (state.?.S > @as(f64, 0.0)))) {
            f1 = state.?.f;
            if (((f1 * dt) > state.?.S)) {
                f1 = (state.?.S / dt);
            }
        } else {
            state.?.T = (state.?.T + dt);
        }
    }
    if ((f1 > @as(f64, 0.0))) {
        f1 = (try rt.M.min_d_d(f1, fa));
        f1 = (try rt.M.max_d_d(f1, @as(f64, 0.0)));
        state.?.F = (state.?.F + (f1 * dt));
        if ((state.?.regen > @as(f64, 0.0))) {
            state.?.S = (state.?.S - (f1 * dt));
            state.?.S = (try rt.M.max_d_d(state.?.S, @as(f64, 0.0)));
        }
    } else {
        state.?.S = (state.?.S + (((state.?.regen * state.?.Smax) * dt) * recovery_factor));
        state.?.S = (try rt.M.min_d_d(state.?.S, state.?.Smax));
    }
    state.?.f = f1;
    return f1;
}

pub fn F_infil__constant_getInfil(p_rate_ftsec: f64, p_precip: f64, p_depth: f64, p_dt: f64) E!f64 {
