}

pub fn F_infil__grnampt_getF2_Infiltration(p_f1: f64, p_c1: f64, p_ks: f64, p_ts: f64) E!f64 {
    var f1 = p_f1;
    _ = &f1;
    var c1 = p_c1;
    _ = &c1;
    var ks = p_ks;
    _ = &ks;
    var ts = p_ts;
    _ = &ts;
    var f2: f64 = f1;
    _ = &f2;
    var f2min: f64 = (f1 + (ks * ts));
    _ = &f2min;
    if ((c1 == @as(f64, 0.0))) {
        return f2min;
    }
    if (((ts < @as(f64, 10.0)) and (f1 > (@as(f64, 0.01) * c1)))) {
        f2 = (f1 + ((ks * (@as(f64, 1.0) + (c1 / f1))) * ts));
        return (try rt.M.max_d_d(f2, f2min));
    }
    var c2: f64 = ((c1 * rt.Math.Log_d((f1 + c1))) - (ks * ts));
    _ = &c2;
    {
        var i: i32 = @as(i32, 1);
        _ = &i;
        {
            while ((i <= @as(i32, 20))) : (i = (i +% 1)) {
                var df2: f64 = ((((f2 - f1) - (c1 * rt.Math.Log_d((f2 + c1)))) + c2) / (@as(f64, 1.0) - (c1 / (f2 + c1))));
                _ = &df2;
                if ((rt.Math.Abs_d(df2) < @as(f64, 1e-05))) {
                    return (try rt.M.max_d_d(f2, f2min));
                }
                f2 = (f2 - df2);
            }
        }
    }
    return f2min;
}

pub fn F_infil__grnampt_getSatInfil_Infiltration(p_s: ?*T_GreenAmptState, p_tstep: f64, p_irate: f64, p_depth: f64, p_ks: f64, p_lu: f64, p_Fumax: f64, p_recovery_factor: f64) E!f64 {
    var s = p_s;
    _ = &s;
    var tstep = p_tstep;
    _ = &tstep;
    var irate = p_irate;
    _ = &irate;
    var depth = p_depth;
    _ = &depth;
    var ks = p_ks;
    _ = &ks;
    var lu = p_lu;
    _ = &lu;
    var Fumax = p_Fumax;
    _ = &Fumax;
    var recovery_factor = p_recovery_factor;
    _ = &recovery_factor;
    var ia: f64 = (irate + (depth / tstep));
    _ = &ia;
    if ((ia < G_F_infil__TINY_Infiltration)) {
        return @as(f64, 0.0);
    }
    s.?.T = ((@as(f64, 5400.0) / lu) / recovery_factor);
    var c1: f64 = ((s.?.S + depth) * s.?.IMD);
    _ = &c1;
    var F2: f64 = (try F_infil__grnampt_getF2_Infiltration(s.?.F, c1, ks, tstep));
    _ = &F2;
    var dF: f64 = (F2 - s.?.F);
    _ = &dF;
    if ((dF > (ia * tstep))) {
        dF = (ia * tstep);
        s.?.saturated = false;
    }
    s.?.F = (s.?.F + dF);
    s.?.Fu = (s.?.Fu + dF);
    s.?.Fu = (try rt.M.min_d_d(s.?.Fu, Fumax));
    return (dF / tstep);
}

pub fn F_infil__grnampt_getUnsatInfil_Infiltration(p_s: ?*T_GreenAmptState, p_tstep: f64, p_irate: f64, p_depth: f64, p_model_type: T_InfilModel, p_ks: f64, p_lu: f64, p_Fumax: f64, p_recovery_factor: f64) E!f64 {
    var s = p_s;
    _ = &s;
    var tstep = p_tstep;
    _ = &tstep;
    var irate = p_irate;
    _ = &irate;
    var depth = p_depth;
    _ = &depth;
    var model_type = p_model_type;
    _ = &model_type;
    var ks = p_ks;
    _ = &ks;
    var lu = p_lu;
    _ = &lu;
    var Fumax = p_Fumax;
    _ = &Fumax;
    var recovery_factor = p_recovery_factor;
    _ = &recovery_factor;
    var ia: f64 = (irate + (depth / tstep));
    _ = &ia;
    if ((ia < G_F_infil__TINY_Infiltration)) {
        ia = @as(f64, 0.0);
    }
    if ((ia == @as(f64, 0.0))) {
        if ((s.?.Fu <= @as(f64, 0.0))) {
            return @as(f64, 0.0);
        }
        var kr: f64 = ((lu / @as(f64, 90000.0)) * recovery_factor);
        _ = &kr;
        var dF: f64 = ((kr * Fumax) * tstep);
        _ = &dF;
        s.?.F = (s.?.F - dF);
        s.?.Fu = (s.?.Fu - dF);
        if ((s.?.Fu <= @as(f64, 0.0))) {
            s.?.Fu = @as(f64, 0.0);
            s.?.F = @as(f64, 0.0);
            s.?.IMD = s.?.IMDmax;
            return @as(f64, 0.0);
        }
        if ((s.?.T <= @as(f64, 0.0))) {
            s.?.IMD = ((Fumax - s.?.Fu) / lu);
            s.?.F = @as(f64, 0.0);
        }
        return @as(f64, 0.0);
    }
    if ((ia <= ks)) {
        var dF_2: f64 = (ia * tstep);
        _ = &dF_2;
        s.?.F = (s.?.F + dF_2);
        s.?.Fu = (s.?.Fu + dF_2);
        s.?.Fu = (try rt.M.min_d_d(s.?.Fu, Fumax));
        if (((model_type == T_InfilModel__GREEN_AMPT) and (s.?.T <= @as(f64, 0.0)))) {
            s.?.IMD = ((Fumax - s.?.Fu) / lu);
            s.?.F = @as(f64, 0.0);
        }
        return ia;
    }
    s.?.T = ((@as(f64, 5400.0) / lu) / recovery_factor);
    var Fs: f64 = (((ks * (s.?.S + depth)) * s.?.IMD) / (ia - ks));
    _ = &Fs;
    if ((s.?.F > Fs)) {
        s.?.saturated = true;
        return (try F_infil__grnampt_getSatInfil_Infiltration(s, tstep, irate, depth, ks, lu, Fumax, recovery_factor));
    }
    if (((s.?.F + (ia * tstep)) < Fs)) {
        var dF_3: f64 = (ia * tstep);
        _ = &dF_3;
        s.?.F = (s.?.F + dF_3);
        s.?.Fu = (s.?.Fu + dF_3);
        s.?.Fu = (try rt.M.min_d_d(s.?.Fu, Fumax));
        return ia;
    }
    var ts: f64 = (tstep - ((Fs - s.?.F) / ia));
    _ = &ts;
    if ((ts <= @as(f64, 0.0))) {
        ts = @as(f64, 0.0);
    }
    var c1: f64 = ((s.?.S + depth) * s.?.IMD);
    _ = &c1;
    var F2: f64 = (try F_infil__grnampt_getF2_Infiltration(Fs, c1, ks, ts));
    _ = &F2;
    if ((F2 > (Fs + (ia * ts)))) {
        F2 = (Fs + (ia * ts));
    }
    var dF_4: f64 = (F2 - s.?.F);
    _ = &dF_4;
    s.?.F = F2;
    s.?.Fu = (s.?.Fu + dF_4);
    s.?.Fu = (try rt.M.min_d_d(s.?.Fu, Fumax));
    s.?.saturated = true;
    return (dF_4 / tstep);
}

