    _ = &conduits;
    var length: f64 = (if ((conduits.?.length.?.a.?[@intCast(rt.cv(u64, row))] > @as(f64, 0.0))) &conduits.?.length.?.a.?[@intCast(rt.cv(u64, row))] else &conduits.?.mod_length.?.a.?[@intCast(rt.cv(u64, row))]).*;
    _ = &length;
