pub fn F_transport_heat__seedBedTemperature(p_ctx: ?*T_SimulationContext) E!void {
    var ctx = p_ctx;
    _ = &ctx;
    var bed: ?*T_BedZoneState = ctx.?.bed_state;
    _ = &bed;
    var nl: i32 = (try T_SimulationContext__n_links(ctx));
    _ = &nl;
    var sc: ?*T_SedimentConfig = ctx.?.heat_config.?.sediment;
    _ = &sc;
    var t0: f64 = (if (sc.?.has_initial_temp) &sc.?.initial_temp else &sc.?.ground_temp).*;
    _ = &t0;
    if (!((try T_BedZoneState__sized(bed, nl)))) {
        (try bed.?.link_temp.?.assign_ul_T(rt.cv(u64, @as(i32, if ((nl > @as(i32, 0))) nl else @as(i32, 0))), t0));
        bed.?.seeded = false;
    }
    if (!(bed.?.seeded)) {
        {
            var v__r1: ?*rt.Vec(f64) = bed.?.link_temp;
            _ = &v__r1;
            {
                var v__i2: i64 = @as(i64, 0);
                _ = &v__i2;
                var v__i2_n: i64 = rt.cv(i64, v__r1.?.n);
                _ = &v__i2_n;
                while ((v__i2 < v__i2_n)) : (v__i2 = (v__i2 +% 1)) {
                    var t: *f64 = &v__r1.?.a.?[@intCast(v__i2)];
                    _ = &t;
                    {
                        t.* = t0;
                    }
                }
            }
        }
        bed.?.seeded = true;
    }
}

pub fn F_transport_heat__applyBedSoluteExchange(p_ctx: ?*T_SimulationContext, p_link_conc: ?[*]f64, p_n_arr: i32, p_offset: i32, p_n_total: i32, p_dt: f64) E!void {
    var ctx = p_ctx;
    _ = &ctx;
    var link_conc = p_link_conc;
    _ = &link_conc;
    var n_arr = p_n_arr;
    _ = &n_arr;
    var offset = p_offset;
    _ = &offset;
    var n_total = p_n_total;
    _ = &n_total;
    var dt = p_dt;
    _ = &dt;
    if (((!((try F_transport_heat__bedExchangeEnabled(ctx))) or !((dt > @as(f64, 0.0)))) or (link_conc == null))) {
        return;
    }
    if ((((n_arr <= @as(i32, 0)) or (offset < @as(i32, 0))) or (n_total < (offset +% n_arr)))) {
        return;
    }
    (try F_transport_heat__seedBedTemperature(ctx));
    var bed: ?*T_BedZoneState = ctx.?.bed_state;
    _ = &bed;
    var nl_all: i32 = (try T_SimulationContext__n_links(ctx));
    _ = &nl_all;
    var need: u64 = (rt.cv(u64, @as(i32, if ((nl_all > @as(i32, 0))) nl_all else @as(i32, 0))) *% rt.cv(u64, n_total));
    _ = &need;
    if (((bed.?.n_species != n_total) or ((try bed.?.link_conc.?.size()) != need))) {
        (try bed.?.link_conc.?.assign_ul_T(need, @as(f64, 0.0)));
        bed.?.n_species = n_total;
    }
    var nl: i32 = (try T_SimulationContext__n_links(ctx));
    _ = &nl;
    var na: u64 = rt.cv(u64, n_arr);
    _ = &na;
    var nt: u64 = rt.cv(u64, n_total);
    _ = &nt;
    var off: u64 = rt.cv(u64, offset);
    _ = &off;
    {
        var j: i32 = @as(i32, 0);
        _ = &j;
        {
            while ((j < nl)) : (j = (j +% 1)) {
                var uj: u64 = rt.cv(u64, j);
                _ = &uj;
                if (((uj < (try ctx.?.heat_state.?.mesh_contact_link.?.size())) and (rt.cv(i32, ctx.?.heat_state.?.mesh_contact_link.?.a.?[@intCast(uj)]) != @as(i32, 0)))) {
                    continue;
                }
                if ((uj >= (try bed.?.link_temp.?.size()))) {
                    break;
                }
                var vol_ft3: f64 = ctx.?.links.?.volume.?.a.?[@intCast(uj)];
                _ = &vol_ft3;
                if (!((vol_ft3 > @as(f64, 0.0)))) {
                    continue;
                }
                var bed_m2: f64 = (try F_transport_heat__linkBedAreaM2(ctx, j));
                _ = &bed_m2;
                if (!((bed_m2 > @as(f64, 0.0)))) {
                    continue;
                }
                var sc: ?*T_SedimentConfig = (try F_transport_heat__sedimentFor(ctx, (try T_HeatElement__link(j))));
                _ = &sc;
                var vol_w: f64 = (vol_ft3 * G_F_transport_heat__kCuFtToCuM);
                _ = &vol_w;
                var vol_b: f64 = (bed_m2 * sc.?.bed_thickness);
                _ = &vol_b;
                var q_exch: f64 = (try F_transport_heat__bedExchangeQ(sc, bed_m2));
                _ = &q_exch;
                if ((!((q_exch > @as(f64, 0.0))) or !((vol_b > @as(f64, 0.0))))) {
                    continue;
                }
                {
                    var s: u64 = @as(u64, 0);
                    _ = &s;
                    {
                        while ((s < na)) : (s = (s +% 1)) {
                            var cw: *f64 = &rt.pat(link_conc, ((uj *% na) +% s)).*;
                            _ = &cw;
                            var cb: *f64 = &bed.?.link_conc.?.a.?[@intCast((((uj *% nt) +% off) +% s))];
                            _ = &cb;
                            var st: ?*T_transport_heat_SolutePairStep = (try F_transport_heat__exchangePair(cw.*, cb.*, vol_w, vol_b, q_exch, dt));
                            _ = &st;
                            cw.* = (cw.* + st.?.dc_w);
                            cb.* = (cb.* + st.?.dc_b);
                        }
                    }
                }
            }
        }
    }
}

pub fn F_transport_heat__anon_transport_components_HeatFluxModules_BedExchange_cpp__phi1_BedExchange(p_z: f64) E!f64 {
