pub fn F_transport_fvkernels__limitSlope(p_a: f64, p_b: f64, p_lim: T_fv_Limiter) E!f64 {
    var a = p_a;
    _ = &a;
    var b = p_b;
    _ = &b;
    var lim = p_lim;
    _ = &lim;
    if (((a * b) <= @as(f64, 0.0))) {
        return @as(f64, 0.0);
    }
    {
        {
            const __sv2 = lim;
            switch (__sv2) {
                1 => {
                    {
                        return (((@as(f64, 2.0) * a) * b) / (a + b));
                    }
                },
                2 => {
                    {
                        {
                            var s: f64 = @as(f64, if ((a > @as(f64, 0.0))) @as(f64, 1.0) else @as(f64, -1.0));
                            _ = &s;
                            return (s * (try rt.M.max_d_d((try rt.M.min_d_d((@as(f64, 2.0) * rt.Math.Abs_d(a)), rt.Math.Abs_d(b))), (try rt.M.min_d_d(rt.Math.Abs_d(a), (@as(f64, 2.0) * rt.Math.Abs_d(b)))))));
                        }
                    }
                },
                else => {
                    {
                        return (if ((rt.Math.Abs_d(a) < rt.Math.Abs_d(b))) &a else &b).*;
                    }
                },
            }
        }
    }
    unreachable;
}

pub fn T_IOThread__start(this: ?*T_IOThread) E!void {
