    this.?.next_sequence_ = (this.?.next_sequence_ +% 1);
    var rc: i32 = (try T_PluginFactory__update_all(this.?.factory_, snap));
    _ = &rc;
    if ((rc != @as(i32, 0))) {
        this.?.last_error_.?.v = rc;
    }
    this.?.tasks_completed_.?.v = (this.?.tasks_completed_.?.v +% @as(i32, 1));
}

pub fn T_IOThread__stop(this: ?*T_IOThread) E!void {
